const today = new Intl.DateTimeFormat('en-CA', {
  timeZone: 'Asia/Seoul',
}).format(new Date());

return items.filter(({ json }) =>
  json.ai_feedback == null &&
  typeof json.reflection === 'string' &&
  json.reflection.trim().length > 0 &&
  typeof json.review_date === 'string' &&
  json.review_date <= today
);

return items.map((item) => {
  let insight = item.json.output;

  if (typeof insight === 'string') {
    try {
      insight = JSON.parse(insight);
    } catch {
      throw new Error('AI 인사이트가 올바른 JSON 형식이 아닙니다.');
    }
  }

  const required = ['core_feedback', 'wins', 'improvements', 'tomorrow_action'];
  if (!insight || required.some((key) => !(key in insight))) {
    throw new Error('AI 인사이트에 필수 항목이 없습니다.');
  }

  const text = [
    insight.core_feedback,
    ...(Array.isArray(insight.wins) ? insight.wins : []),
    ...(Array.isArray(insight.improvements) ? insight.improvements : []),
    insight.tomorrow_action,
  ].join(' ').trim();

  const characterCount = Array.from(text).length;
  if (characterCount < 230 || characterCount > 250) {
    throw new Error(`AI 인사이트 분량이 ${characterCount}자입니다. 230~250자로 다시 생성해야 합니다.`);
  }

  return {
    json: {
      ...item.json,
      output: insight,
      character_count: characterCount,
    },
    pairedItem: item.pairedItem,
  };
});
